"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant3 from "./components/empty-states/variants/04-board";
const variants = {"board": Variant3};
export interface ArtemisEmptyStatesProps { className?: string; variant?: "board"; }
export function ArtemisEmptyStates({ className, variant = "board" }: ArtemisEmptyStatesProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
export default function EmptyStatesBoard() {
    const reducedMotion = useReducedMotion();
    const [boardReady, setBoardReady] = useState(Boolean(reducedMotion));
    const [cardReady, setCardReady] = useState(Boolean(reducedMotion));
    const [hintReady, setHintReady] = useState(Boolean(reducedMotion));
    useEffect(() => {
        if (reducedMotion) {
            setBoardReady(true);
            setCardReady(true);
            setHintReady(true);
            return;
        }
        const boardTimer = window.setTimeout(() => setBoardReady(true), 80);
        const cardTimer = window.setTimeout(() => setCardReady(true), 240);
        const hintTimer = window.setTimeout(() => setHintReady(true), 420);
        return () => {
            window.clearTimeout(boardTimer);
            window.clearTimeout(cardTimer);
            window.clearTimeout(hintTimer);
        };
    }, [reducedMotion]);
    return (<>
      <section className="art:mx-auto art:flex art:w-full art:max-w-[600px] art:flex-col art:justify-between art:overflow-hidden art:text-foreground">
        <div className="art:flex art:items-start art:justify-between art:gap-6">
          <div>
            <span className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.18em]">
              {"Projects / empty"}
            </span>
            <h2 className="art:mt-2 art:max-w-md art:text-balance art:tracking-[-0.04em] art:text-4xl art:font-medium">
              {"Start with one thing."}
            </h2>
          </div>
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:mt-1 art:size-5 art:text-muted-foreground" aria-hidden="true">
            <path d="M7 7h10v10"/>
            <path d="M7 17 17 7"/>
          </svg>
        </div>
        <motion.div aria-hidden="true" className="art:relative art:my-6 art:grid art:min-h-[185px] art:grid-cols-3 art:gap-2" initial={{ opacity: 0, y: 14 }} animate={boardReady ? { opacity: 1, y: 0 } : undefined} transition={reducedMotion ? { duration: 0 } : ARTEMIS_SPRING_PANEL}>
          <div className="art:relative art:border art:border-border art:p-2">
            <div className="art:flex art:items-center art:justify-between art:gap-2 art:border-b art:border-border art:pb-2 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em] art:@min-[640px]/artemis:text-xs">
              <span>
                {"Queue"}
              </span>
              <span>
                {"00"}
              </span>
            </div>
          </div>
          <div className="art:relative art:border art:border-border art:p-2">
            <div className="art:flex art:items-center art:justify-between art:gap-2 art:border-b art:border-border art:pb-2 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em] art:@min-[640px]/artemis:text-xs">
              <span>
                {"Doing"}
              </span>
              <span>
                {"00"}
              </span>
            </div>
          </div>
          <div className="art:relative art:border art:border-border art:p-2">
            <div className="art:flex art:items-center art:justify-between art:gap-2 art:border-b art:border-border art:pb-2 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em] art:@min-[640px]/artemis:text-xs">
              <span>
                {"Done"}
              </span>
              <span>
                {"00"}
              </span>
            </div>
          </div>
          <motion.div className="art:absolute art:left-[7%] art:top-[31%] art:w-[27%] art:border art:border-foreground art:bg-background art:p-3" initial={{ opacity: 0, x: -24, rotate: -3 }} animate={cardReady ? { opacity: 1, x: 0, rotate: 0 } : undefined} transition={reducedMotion ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}>
            <div className="art:mb-3 art:flex art:items-center art:justify-between">
              <span className="art:size-2 art:rounded-full art:bg-primary"/>
              <span className="art:font-mono art:text-xs art:text-muted-foreground">
                {"001"}
              </span>
            </div>
            <div className="art:h-1.5 art:w-4/5 art:bg-foreground"/>
            <div className="art:mt-2 art:h-1.5 art:w-1/2 art:bg-muted-foreground/30"/>
          </motion.div>
          <motion.div className="art:absolute art:left-[31%] art:top-[64%] art:flex art:items-center art:gap-1.5 art:font-mono art:text-xs art:text-muted-foreground" initial={{ opacity: 0, x: -12, y: 12 }} animate={hintReady ? { opacity: 1, x: 0, y: 0 } : undefined} transition={reducedMotion ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-mouse-pointer2 art:lucide-mouse-pointer-2 art:size-4 art:fill-background" aria-hidden="true">
              <path d="M4.037 4.688a.495.495 0 0 1 .651-.651l16 6.5a.5.5 0 0 1-.063.947l-6.124 1.58a2 2 0 0 0-1.438 1.435l-1.579 6.126a.5.5 0 0 1-.947.063z"/>
            </svg>
            {"drag to begin"}
          </motion.div>
        </motion.div>
        <div className="art:flex art:items-end art:justify-between art:gap-5 art:border-t art:border-border art:pt-5">
          <p className="art:max-w-[250px] art:text-pretty art:text-muted-foreground art:text-xs art:leading-5 art:@min-[640px]/artemis:text-sm">
            {"Create the first project. The rest of the board can wait."}
          </p>
          <ArtemisButton size="sm" className="art:shrink-0 art:h-9">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-plus art:size-3.5" aria-hidden="true">
              <path d="M5 12h14"/>
              <path d="M12 5v14"/>
            </svg>
            {"New project"}
          </ArtemisButton>
        </div>
      </section>
    </>);
}
